def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_def = 0
    my_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1

    if n >= 10 and opp_def > n * 0.5:
        return 'D'

    my_def_opp = 0
    opp_retaliate = 0
    for i in range(n-1):
        if history[i][0] == 'D':
            my_def_opp += 1
            if history[i+1][1] == 'D':
                opp_retaliate += 1

    non_retaliatory = (my_def_opp > 0 and opp_retaliate == 0)

    if n >= 95:
        if non_retaliatory:
            return 'D'
        if opp_last == 'C':
            return 'C'
        else:
            return 'D'

    if non_retaliatory and opp_last == 'C':
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    if opp_last == 'D':
        if my_last == 'C':
            recent_dd = 0
            for i in range(max(0, n-3), n):
                if history[i][0] == 'D' and history[i][1] == 'D':
                    recent_dd += 1
            if recent_dd > 0:
                if rng.random() < 0.5:
                    return 'C'
            return 'D'
        else:
            dd = 0
            for i in range(n-1, -1, -1):
                if history[i][0] == 'D' and history[i][1] == 'D':
                    dd += 1
                else:
                    break
            p = min(0.8, 0.2 * dd)
            if rng.random() < p:
                return 'C'
            return 'D'
    else:
        if my_last == 'D':
            return 'C'
        else:
            if n > 20 and opp_def == 0:
                if rng.random() < 0.05:
                    return 'D'
            return 'C'
